#!/bin/bash
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"
set -a
source ./network.env
set +a
# Root-controlled env file, generated by install.sh.
docker network inspect android-build-net >/dev/null 2>&1 || docker network create --subnet 172.30.0.0/24 --label local.android-build.managed=true android-build-net
python3 ./configure_network.py
